import{_ as e,c as t,o as r,ag as i}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"流量入口与 Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"devops/networking/traffic-routing.md","filePath":"devops/networking/traffic-routing.md","lastUpdated":1788689791000}'),o={name:"devops/networking/traffic-routing.md"};function l(n,a,s,d,c,g){return r(),t("div",null,a[0]||(a[0]=[i('<h1 id="流量入口与-gateway" tabindex="-1">流量入口与 Gateway <a class="header-anchor" href="#流量入口与-gateway" aria-label="Permalink to &quot;流量入口与 Gateway&quot;">​</a></h1><h2 id="组件职责" tabindex="-1">组件职责 <a class="header-anchor" href="#组件职责" aria-label="Permalink to &quot;组件职责&quot;">​</a></h2><ul><li><strong>反向代理</strong>：代表后端接收请求，处理 TLS、路由、压缩和访问日志。</li><li><strong>负载均衡器</strong>：在多个健康实例间分配连接或请求。</li><li><strong>Kubernetes Service</strong>：提供集群内稳定虚拟入口。</li><li><strong>Ingress</strong>：用较简洁的 HTTP/HTTPS 规则暴露服务。</li><li><strong>Gateway API</strong>：将基础设施所有者、集群运维和应用团队的配置职责拆分，并支持更丰富路由模型。</li></ul><h2 id="生产配置" tabindex="-1">生产配置 <a class="header-anchor" href="#生产配置" aria-label="Permalink to &quot;生产配置&quot;">​</a></h2><ul><li>TLS 版本、证书来源、续期和到期告警必须明确。</li><li>连接、请求、空闲和上游超时应逐层协调。</li><li>仅对幂等请求谨慎重试，并限制次数，避免放大故障。</li><li>传递并校验 <code>X-Forwarded-*</code> 或标准 <code>Forwarded</code> 信息，只信任已知代理。</li><li>配置请求体上限、速率限制和必要的安全响应头。</li><li>访问日志关联 Trace ID，并对敏感参数和 Header 脱敏。</li></ul><h2 id="发布流量" tabindex="-1">发布流量 <a class="header-anchor" href="#发布流量" aria-label="Permalink to &quot;发布流量&quot;">​</a></h2><p>蓝绿和金丝雀发布可通过服务选择器、权重路由或专用发布控制器实现。流量扩大必须绑定错误率、延迟和业务成功率，而不是只等待固定时间。</p>',7)]))}const _=e(o,[["render",l]]);export{u as __pageData,_ as default};
